shellCommands.command:
/bin/bash -lc "cat > src/App.tsx <<'EOF'
import {PageConstructor, PageConstructorProvider} from '@gravity-ui/page-constructor';
import type {PageContent} from '@gravity-ui/page-constructor';
import './App.css';

const features = [
  {number: '01', title: 'Время под контролем', text: 'Запускайте таймер и занимайтесь делом. Все часы сохранятся в нужном проекте.'},
  {number: '02', title: 'Команда в одном ритме', text: 'Видите загрузку каждого и распределяйте задачи без лишних встреч и сообщений.'},
  {number: '03', title: 'Понятная картина дня', text: 'Узнайте, куда уходит время. Простые отчёты помогут точнее планировать работу.'},
];

// All HTML here is static, trusted page copy, not user-provided content.
const content: PageContent = {
  animated: false,
  blocks: [
    {
      type: 'header-block',
      className: 'tempo-hero',
      width: 'l',
      centered: true,
      verticalOffset: '0',
      indent: {top: '0', bottom: 'xl'},
      overtitle: '<span class=\"brand-row\"><span class=\"wordmark\">tempo<span class=\"wordmark-dot\">.</span></span><span class=\"brand-note\">Время для важного</span></span><span class=\"hero-kicker\">УЧЁТ ВРЕМЕНИ ДЛЯ НЕБОЛЬШИХ КОМАНД</span>',
      title: '<span class=\"hero-line\">Меньше рутины.</span><span class=\"hero-line hero-accent\">Больше фокуса.</span>',
      description: '<span class=\"hero-description\">Всё время команды — в одном месте.<br class=\"desktop-break\" /> Учитывайте часы, следите за проектами и берегите фокус.</span>',
    },
    {
      type: 'extended-features-block',
      animated: false,
      indent: {top: '0', bottom: 'xl'},
      colSizes: {all: 12, sm: 12, md: 4},
      items: features.map(({number, title, text}) => ({
        title: "'`<span class="feature-heading"><span class="feature-number">${number} /</span><span class="feature-title">${title}</span></span>`,
        text: `<p class="feature-description">${text}</p>`,
      })),
    },
    {
      type: '"'banner-block',
      className: 'tempo-cta',
      animated: false,
      indent: {top: '0', bottom: 'm'},
      title: '<span class=\"cta-heading\">Найдите свой рабочий ритм.</span>',
      subtitle: '<span class=\"cta-description\">Начните с Tempo. Напишите нам, чтобы подключить команду.</span>',
      color: 'var(--g-color-base-generic-ultralight)',
      button: {
        text: 'Подключить команду  ↗',
        theme: 'action',
        url: 'mailto:hello@tempo.team?subject=Подключение%20команды%20к%20Tempo',
      },
    },
  ],
};

export function App() {
  return (
    <main className=\"landing\">
      <PageConstructorProvider locale={{lang: 'ru', tld: 'ru'}} theme=\"light\">
        <PageConstructor content={content} />
      </PageConstructorProvider>
    </main>
  );
}
EOF
cat > src/App.css <<'EOF'
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--g-color-base-background);
  color: var(--g-color-text-primary);
}

.landing {
  max-width: 1232px;
  margin-inline: auto;
  padding: var(--g-spacing-8) 0 var(--g-spacing-4);
  --pc-text-header-color: var(--g-color-text-primary);
  --pc-border-radius: var(--g-border-radius-xl);
  --g-text-display-4-font-size: 80px;
  --g-text-display-4-line-height: 88px;
  --g-text-display-2-font-size: 30px;
  --g-text-display-2-line-height: 40px;
  --g-text-header-1-font-size: 21px;
  --g-text-header-1-line-height: 28px;
}

.brand-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--g-spacing-4);
  margin-bottom: calc(var(--g-spacing-10) + var(--g-spacing-6));
  text-align: left;
}

.wordmark {
  flex-shrink: 0;
  font-size: var(--g-text-display-2-font-size);
  line-height: var(--g-text-display-2-line-height);
  font-weight: 750;
  letter-spacing: -1.5px;
}

.wordmark-dot,
.hero-accent {
  color: var(--g-color-text-warning-heavy);
}

.brand-note {
  min-width: 0;
  font-size: var(--g-text-body-1-font-size);
  color: var(--g-color-text-secondary);
  letter-spacing: 0.2px;
}

.hero-kicker {
  display: inline-block;
  margin-bottom: var(--g-spacing-6);
  padding: var(--g-spacing-2) var(--g-spacing-3);
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-xl);
  color: var(--g-color-text-secondary);
  font-size: var(--g-text-caption-2-font-size);
  line-height: var(--g-text-caption-2-line-height);
  font-weight: 500;
  letter-spacing: 1.2px;
}

.hero-line {
  display: block;
  font-weight: 650;
  letter-spacing: -3.8px;
}

.hero-description {
  display: block;
  margin: var(--g-spacing-6) auto 0;
  color: var(--g-color-text-secondary);
  font-size: var(--g-text-body-3-font-size);
  line-height: 28px;
  font-weight: 400;
}

.feature-heading {
  display: block;
  padding-top: var(--g-spacing-6);
  border-top: 1px solid var(--g-color-line-generic);
}

.feature-number {
  display: block;
  margin-bottom: var(--g-spacing-6);
  color: var(--g-color-text-secondary);
  font-size: var(--g-text-caption-2-font-size);
  line-height: var(--g-text-caption-2-line-height);
  font-weight: 400;
  letter-spacing: 1px;
}

.feature-title {
  display: block;
  font-weight: 600;
  letter-spacing: -0.45px;
}

.landing .feature-description {
  max-width: 305px;
  margin: var(--g-spacing-3) 0 0;
  color: var(--g-color-text-secondary);
  font-size: var(--g-text-body-2-font-size);
  line-height: 24px;
}

.cta-heading {
  font-weight: 600;
  letter-spacing: -0.8px;
}

.cta-description {
  display: block;
  max-width: 420px;
  color: var(--g-color-text-secondary);
  font-size: var(--g-text-body-2-font-size);
  line-height: 24px;
}

.tempo-cta {
  --g-button-border-radius: var(--g-border-radius-m);
  --g-button-background-color: var(--g-color-text-primary);
  --g-button-background-color-hover: var(--g-color-text-secondary);
  --g-button-text-color: var(--g-color-base-background);
  --g-button-text-color-hover: var(--g-color-base-background);
}

/* Narrow layout customization of BannerCard internals, pinned to
   @gravity-ui/page-constructor 8.24.1. The block exposes no layout CSS API.
   Upstream candidate: compact horizontal banner with no media. */
.tempo-cta .pc-banner-card__content {
  min-height: 0;
}

.tempo-cta .pc-banner-card__info {
  flex: 1;
  min-width: 0;
  flex-direction: row;
  align-items: center;
  gap: var(--g-spacing-8);
  padding: var(--g-spacing-9) var(--g-spacing-10);
}

.tempo-cta .pc-banner-card__image {
  display: none;
}

.tempo-cta .pc-banner-card__button {
  flex-shrink: 0;
  margin-top: 0;
}

@media (max-width: 768px) {
  .landing {
    padding-top: var(--g-spacing-4);
    --g-text-display-3-font-size: 56px;
    --g-text-display-3-line-height: 64px;
  }

  .brand-row {
    margin-bottom: var(--g-spacing-10);
  }

  .hero-line {
    letter-spacing: -2.5px;
  }

  .landing .feature-description {
    max-width: none;
  }

  .feature-number {
    margin-bottom: var(--g-spacing-3);
  }

  .tempo-cta .pc-banner-card__info {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--g-spacing-6);
    padding: var(--g-spacing-7);
  }
}

@media (max-width: 576px) {
  .tempo-hero {
    --g-text-display-2-font-size: 43px;
    --g-text-display-2-line-height: 50px;
  }

  .wordmark {
    font-size: 30px;
    line-height: 40px;
  }

  .hero-line {
    letter-spacing: -1.8px;
  }

  .hero-kicker {
    font-size: 9px;
    letter-spacing: 0.8px;
    padding-inline: var(--g-spacing-2);
  }

  .hero-description {
    font-size: var(--g-text-body-2-font-size);
    line-height: 24px;
  }

  .desktop-break {
    display: none;
  }

  .cta-heading {
    display: block;
    font-size: var(--g-text-header-1-font-size);
    line-height: 28px;
    letter-spacing: -0.4px;
  }
}
EOF"
